<template>
  <div class="management-page">
    <aside class="sidebar"><div class="sidebar-header"><div class="logo"><i class="fas fa-leaf"></i><span>Herbier Admin</span></div></div>
      <nav class="sidebar-nav"><router-link to="/dashboard" class="nav-item"><i class="fas fa-tachometer-alt"></i><span>Tableau de bord</span></router-link><router-link to="/plantes" class="nav-item"><i class="fas fa-leaf"></i><span>Plantes</span></router-link><router-link to="/equipe" class="nav-item"><i class="fas fa-users"></i><span>Équipe</span></router-link><router-link to="/partenaires" class="nav-item"><i class="fas fa-handshake"></i><span>Partenaires</span></router-link><router-link to="/slides" class="nav-item active"><i class="fas fa-images"></i><span>Slides</span></router-link><router-link to="/projets" class="nav-item"><i class="fas fa-project-diagram"></i><span>Projets</span></router-link><router-link to="/activites" class="nav-item"><i class="fas fa-chart-line"></i><span>Activités</span></router-link><router-link to="/temoignages" class="nav-item"><i class="fas fa-comment-dots"></i><span>Témoignages</span></router-link><router-link to="/publications" class="nav-item"><i class="fas fa-book"></i><span>Publications</span></router-link><router-link to="/statistiques" class="nav-item"><i class="fas fa-chart-bar"></i><span>Statistiques</span></router-link><router-link to="/settings" class="nav-item"><i class="fas fa-cog"></i><span>Paramètres</span></router-link></nav>
      <div class="sidebar-footer"><button @click="logout" class="logout-btn"><i class="fas fa-sign-out-alt"></i><span>Déconnexion</span></button></div>
    </aside>
    <main class="main-content">
      <header class="top-bar"><div class="page-title"><h1>Gestion des slides</h1><p>Gérez le carrousel d'images de la page d'accueil</p></div><button @click="openModal" class="btn-primary"><i class="fas fa-plus"></i> Nouveau slide</button></header>
      <div class="data-table"><table><thead><tr><th>Image</th><th>Titre</th><th>Texte</th><th>Ordre</th><th>Actif</th><th>Actions</th></tr></thead>
        <tbody><tr v-for="slide in slides" :key="slide.id"><td><img :src="slide.image || '/images/slide-placeholder.jpg'" class="table-image" @error="handleImageError"></td><td><strong>{{ slide.titre }}</strong></td><td>{{ slide.texte_botanique | truncate }}</td><td>{{ slide.ordre }}</td><td><span :class="['badge', slide.actif ? 'active' : 'inactive']">{{ slide.actif ? 'Actif' : 'Inactif' }}</span></td><td class="actions"><button @click="editItem(slide)" class="btn-edit"><i class="fas fa-edit"></i></button><button @click="deleteItem(slide)" class="btn-delete"><i class="fas fa-trash"></i></button></td></tr>
          <tr v-if="slides.length === 0"><td colspan="6" class="empty">Aucun slide trouvé</td></tr>
        </tbody></table></div>
      <div class="modal" :class="{ active: showModal }" @click.self="closeModal"><div class="modal-content"><div class="modal-header"><h2>{{ editingId ? 'Modifier' : 'Ajouter' }} un slide</h2><button class="close" @click="closeModal"><i class="fas fa-times"></i></button></div>
        <form @submit.prevent="saveItem"><div class="form-group"><label>Titre *</label><input type="text" v-model="form.titre" required></div><div class="form-group"><label>Texte botanique *</label><textarea v-model="form.texte_botanique" rows="4" required></textarea></div><div class="form-group"><label>Image URL</label><input type="text" v-model="form.image" placeholder="/images/..."></div><div class="form-group"><label>Ordre</label><input type="number" v-model="form.ordre"></div><div class="form-group"><label>Actif</label><input type="checkbox" v-model="form.actif"></div>
        <div class="modal-footer"><button type="button" class="btn-secondary" @click="closeModal">Annuler</button><button type="submit" class="btn-primary">Enregistrer</button></div></form></div></div>
      <div v-if="toastMessage" class="toast" :class="toastType"><i :class="toastType === 'success' ? 'fas fa-check-circle' : 'fas fa-exclamation-circle'"></i><span>{{ toastMessage }}</span></div>
    </main>
  </div>
</template>
<script>
import { useAuthStore } from '../stores/auth'
import axios from 'axios'
export default { name: 'SlidesManagement', filters: { truncate: v => v?.length > 80 ? v.substring(0,80)+'...' : v || '' }, data() { return { slides: [], showModal: false, editingId: null, form: { titre: '', texte_botanique: '', image: '', ordre: 0, actif: true }, toastMessage: '', toastType: '' } }, mounted() { this.loadData() }, methods: { async loadData() { try { const res = await axios.get('http://localhost:8001/api/herbier-data/'); this.slides = res.data.slides || [] } catch(e) { console.error(e) } }, openModal() { this.editingId = null; this.form = { titre: '', texte_botanique: '', image: '', ordre: 0, actif: true }; this.showModal = true }, editItem(item) { this.editingId = item.id; this.form = { ...item }; this.showModal = true }, async saveItem() { try { let slides = [...this.slides]; if (this.editingId) { const i = slides.findIndex(s => s.id === this.editingId); slides[i] = { ...this.form, id: this.editingId } } else { slides.push({ ...this.form, id: Date.now() }) } await axios.put('http://localhost:8001/api/herbier-data/', { ...(await axios.get('http://localhost:8001/api/herbier-data/')).data, slides }); this.slides = slides; this.showToast('success', this.editingId ? 'Slide modifié' : 'Slide ajouté'); this.closeModal() } catch(e) { this.showToast('error', 'Erreur') } }, async deleteItem(item) { if(confirm('Supprimer ce slide ?')) { const slides = this.slides.filter(s => s.id !== item.id); await axios.put('http://localhost:8001/api/herbier-data/', { ...(await axios.get('http://localhost:8001/api/herbier-data/')).data, slides }); this.slides = slides; this.showToast('success', 'Slide supprimé') } }, closeModal() { this.showModal = false }, showToast(type, msg) { this.toastType = type; this.toastMessage = msg; setTimeout(() => { this.toastMessage = '' }, 3000) }, handleImageError(e) { e.target.src = '/images/slide-placeholder.jpg' }, async logout() { await useAuthStore().logout(); this.$router.push('/login') } } }
</script>
<style scoped>/* Styles identiques aux autres pages */ .management-page { display: flex; min-height: 100vh; background: #f5f7fa; } .sidebar { width: 280px; background: linear-gradient(180deg, #1a472a 0%, #0d3b0f 100%); color: white; position: fixed; height: 100vh; } .sidebar-header { padding: 30px 24px; border-bottom: 1px solid rgba(255,255,255,0.1); } .logo { display: flex; align-items: center; gap: 12px; font-size: 20px; font-weight: bold; } .logo i { font-size: 28px; color: #FFD700; } .sidebar-nav { flex: 1; padding: 20px 16px; display: flex; flex-direction: column; gap: 4px; } .nav-item { display: flex; align-items: center; gap: 12px; padding: 12px 16px; color: rgba(255,255,255,0.8); text-decoration: none; border-radius: 12px; } .nav-item:hover, .nav-item.active { background: #FFD700; color: #1a472a; } .sidebar-footer { padding: 20px; border-top: 1px solid rgba(255,255,255,0.1); } .logout-btn { width: 100%; display: flex; align-items: center; gap: 12px; padding: 12px 16px; background: rgba(255,255,255,0.1); border: none; border-radius: 12px; color: white; cursor: pointer; } .main-content { flex: 1; margin-left: 280px; } .top-bar { background: white; padding: 20px 30px; display: flex; justify-content: space-between; } .page-title h1 { font-size: 24px; color: #1a472a; } .btn-primary { padding: 10px 20px; background: linear-gradient(135deg, #32CD32, #228B22); color: white; border: none; border-radius: 10px; cursor: pointer; } .data-table { background: white; margin: 20px; border-radius: 15px; overflow: auto; } table { width: 100%; } th, td { padding: 15px; text-align: left; } th { background: #f8f9fa; } .table-image { width: 60px; height: 50px; border-radius: 10px; object-fit: cover; } .badge.active { background: #28a745; color: white; padding: 4px 10px; border-radius: 20px; font-size: 12px; } .badge.inactive { background: #dc3545; color: white; padding: 4px 10px; border-radius: 20px; font-size: 12px; } .actions { display: flex; gap: 8px; } .btn-edit, .btn-delete { padding: 6px 10px; border: none; border-radius: 5px; cursor: pointer; } .btn-edit { background: #ffc107; } .btn-delete { background: #dc3545; color: white; } .modal { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.7); display: flex; align-items: center; justify-content: center; z-index: 1000; visibility: hidden; opacity: 0; } .modal.active { visibility: visible; opacity: 1; } .modal-content { background: white; border-radius: 20px; width: 90%; max-width: 600px; } .modal-header { display: flex; justify-content: space-between; padding: 20px; } .close { background: none; border: none; font-size: 20px; cursor: pointer; } form { padding: 20px; } .form-group { margin-bottom: 15px; display: flex; flex-direction: column; gap: 5px; } .form-group input, .form-group textarea { padding: 10px; border: 1px solid #ddd; border-radius: 8px; } .modal-footer { display: flex; justify-content: flex-end; gap: 10px; margin-top: 20px; } .btn-secondary { padding: 10px 20px; background: #f5f5f5; border: none; border-radius: 8px; cursor: pointer; } .toast { position: fixed; bottom: 20px; right: 20px; padding: 12px 20px; border-radius: 10px; display: flex; align-items: center; gap: 10px; z-index: 1100; } .toast.success { background: #28a745; color: white; } .toast.error { background: #dc3545; color: white; } .empty { text-align: center; padding: 40px; } @media (max-width: 768px) { .sidebar { width: 80px; } .sidebar-nav span, .sidebar-footer span, .logo span { display: none; } .main-content { margin-left: 80px; } }</style>
